<script setup lang="ts">
const props=defineProps<{periodStart:string;periodEnd:string}>();const{listFinancialHistory}=useAppData();const history=ref<any[]>([]),total=ref(0),historyLoading=ref(false),historyError=ref('');const resourceLabel=(resource:string)=>({products:'Produto',filaments:'Filamento',printers:'Impressora',marketplaces:'Marketplace'}[resource]||resource);const historyTitle=(entry:any)=>`${resourceLabel(entry.resource)} #${entry.resourceId}`;const load=async()=>{historyLoading.value=true;historyError.value='';try{const page=await listFinancialHistory({from:props.periodStart,to:props.periodEnd,limit:100});history.value=page.items;total.value=page.total}catch(error:any){historyError.value=error?.data?.error||'Histórico financeiro indisponível para este perfil.'}finally{historyLoading.value=false}};watch(()=>[props.periodStart,props.periodEnd],load,{immediate:true})</script>
<template><PanelCard title="Histórico de alterações financeiras" subtitle="Versões de custos, preços e taxas do período selecionado."><div v-if="historyLoading" class="empty-state">Carregando histórico...</div><div v-else-if="historyError" class="empty-state">{{historyError}}</div><div v-else-if="!history.length" class="empty-state">Ainda não há alterações financeiras no período.</div><div v-else class="table-scroll"><table class="data-table"><thead><tr><th>Data</th><th>Recurso</th><th>Origem</th><th>Valores registrados</th></tr></thead><tbody><tr v-for="entry in history" :key="entry.id"><td>{{new Date(entry.createdAt).toLocaleString('pt-BR')}}</td><td>{{historyTitle(entry)}}</td><td>{{entry.source}}</td><td><span v-for="(value,key) in entry.snapshot" :key="key" class="history-value">{{key}}: {{typeof value==='number'?formatCurrency(value):value}}</span></td></tr></tbody></table><p v-if="total>history.length" class="history-note">Mostrando os 100 registros mais recentes de {{total}}. Use a exportação para obter o período completo.</p></div></PanelCard></template>
<style scoped>.history-value{display:inline-block;margin:2px 6px 2px 0;padding:4px 7px;border-radius:6px;background:#f1f4f8;font-size:12px}.history-note{padding:0 16px;color:#687386;font-size:12px}</style>
